--
-- Table structure for table `o_order`
--

DROP TABLE IF EXISTS `o_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `o_order` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_no` char(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对外业务单号',
  `client_order_no` char(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '前端幂等键',
  `user_id` bigint unsigned NOT NULL COMMENT '下单用户,故意不建外键:订单表写入最频繁且需独立归档',
  `merchant_id` bigint unsigned NOT NULL COMMENT '所属商家,不建外键以便商家注销后订单仍可查',
  `pickup_point_id` bigint unsigned DEFAULT NULL COMMENT '自提点 id',
  `fulfillment_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PICKUP' COMMENT 'PICKUP 自取/DELIVERY 配送',
  `biz_date` date NOT NULL COMMENT '营业日',
  `meal_period` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LUNCH' COMMENT 'BREAKFAST/LUNCH/DINNER/NIGHT',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_PAYMENT' COMMENT '订单状态',
  `item_amount` int unsigned NOT NULL DEFAULT '0' COMMENT '菜品金额分',
  `pack_fee` int unsigned NOT NULL DEFAULT '0' COMMENT '打包费分',
  `delivery_fee` int unsigned NOT NULL DEFAULT '0' COMMENT '配送费分',
  `discount_amount` int unsigned NOT NULL DEFAULT '0' COMMENT '优惠分',
  `coupon_id` bigint unsigned DEFAULT NULL COMMENT '本单核销的用户券 id,未用券为 NULL',
  `pay_amount` int unsigned NOT NULL COMMENT '实付分',
  `pickup_code` char(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '取餐码,未出餐前为 NULL,NULL 不参与唯一约束',
  `expect_take_at` datetime(3) DEFAULT NULL COMMENT '预计可取时间',
  `pickup_deadline_at` datetime(3) DEFAULT NULL COMMENT '超时未取时间点',
  `taken_at` datetime(3) DEFAULT NULL COMMENT '实际核销时间',
  `expire_at` datetime(3) NOT NULL COMMENT '支付超时时间点',
  `paid_at` datetime(3) DEFAULT NULL,
  `accepted_at` datetime(3) DEFAULT NULL,
  `ready_at` datetime(3) DEFAULT NULL,
  `finished_at` datetime(3) DEFAULT NULL,
  `cancelled_at` datetime(3) DEFAULT NULL,
  `cancel_reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '取消原因',
  `cancel_by` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'USER/MERCHANT/PLATFORM/TIMEOUT/STOCK',
  `merchant_name_snapshot` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商家名快照',
  `pickup_point_name_snapshot` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '自提点快照',
  `contact_name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '联系人',
  `contact_phone` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `dorm_address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '配送地址快照',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '备注',
  `item_count` smallint unsigned NOT NULL DEFAULT '0' COMMENT '总份数',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_o_order_no` (`order_no`),
  UNIQUE KEY `uk_o_client_order` (`user_id`,`client_order_no`),
  UNIQUE KEY `uk_o_pickup_code` (`merchant_id`,`biz_date`,`pickup_code`),
  KEY `idx_o_user_list` (`user_id`,`biz_date`,`id`),
  KEY `idx_o_merchant_board` (`merchant_id`,`status`,`biz_date`,`id`),
  KEY `idx_o_timeout` (`status`,`expire_at`),
  KEY `idx_o_pending_board` (`status`,`pickup_deadline_at`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单主表';
/*!40101 SET character_set_client = @saved_cs_client */;

