--
-- Table structure for table `o_order_item`
--

DROP TABLE IF EXISTS `o_order_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `o_order_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `order_no` char(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冗余单号',
  `dish_id` bigint unsigned NOT NULL COMMENT '仅用于销量回溯',
  `dish_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜名快照',
  `dish_image` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图片快照',
  `category_name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '分类名快照',
  `option_text` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '规格可读串',
  `option_json` json DEFAULT NULL COMMENT '结构化规格',
  `unit_price` int unsigned NOT NULL COMMENT '成交单价分',
  `origin_unit_price` int unsigned NOT NULL DEFAULT '0' COMMENT '划线原价分,0 无折扣',
  `pack_fee` int unsigned NOT NULL DEFAULT '0' COMMENT '行打包费分',
  `discount_amount` int unsigned NOT NULL DEFAULT '0' COMMENT '行分摊优惠分',
  `quantity` smallint unsigned NOT NULL COMMENT '份数',
  `line_amount` int unsigned NOT NULL COMMENT '行小计分',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_o_item_order` (`order_id`),
  KEY `idx_o_item_dish_stat` (`dish_id`,`created_at`),
  CONSTRAINT `fk_o_item_order` FOREIGN KEY (`order_id`) REFERENCES `o_order` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单明细快照';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `o_order_item`
--

LOCK TABLES `o_order_item` WRITE;
/*!40000 ALTER TABLE `o_order_item` DISABLE KEYS */;
