--
-- Table structure for table `o_order_status_log`
--

DROP TABLE IF EXISTS `o_order_status_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `o_order_status_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `from_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原状态,下单产生的首条为 NULL',
  `to_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '新状态',
  `operator_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'USER/MERCHANT/PLATFORM/SYSTEM',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '操作者 id',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '操作者名称快照',
  `note` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '备注',
  `client_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_o_log_order` (`order_id`,`id`),
  KEY `idx_o_log_time` (`created_at`),
  CONSTRAINT `fk_o_log_order` FOREIGN KEY (`order_id`) REFERENCES `o_order` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单状态流转日志';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `o_order_status_log`
--

LOCK TABLES `o_order_status_log` WRITE;
/*!40000 ALTER TABLE `o_order_status_log` DISABLE KEYS */;
